// Astro provides this virtual module during the content-collection build.
// @ts-expect-error The module is generated by Astro and may not be resolved by standalone TypeScript language services.
import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';
import { defineConfig } from 'astro/config';

export default defineConfig({
  site: 'https://andresvallejoT-T.github.io', // Tu dominio en GitHub Pages
  base: '/page-gp',                           // El nombre exacto de tu repositorio
});
// Cada archivo .md de src/content/secciones es una sección de la página.
const secciones = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/secciones' }),
  schema: z.object({
    titulo: z.string(),
    orden: z.number(),
  }),
});

export const collections = { secciones };
